def test_add_records_a_percentage_split(run):
    code, out, _ = run(
        "add", "--paid-by", "alice", "--amount", "10.00", "--description", "Taxi",
        "--percent", "alice=50", "--percent", "bob=30", "--percent", "carol=20",
    )  # fmt: skip
    assert code == 0
    assert out == "added #1: 10.00 for Taxi\n"
    _, out, _ = run("balances")
    assert out == "alice 5.00\nbob -3.00\ncarol -2.00\n"


def test_percentages_not_adding_up_to_100_are_rejected(run):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "10", "--description", "x", "--percent", "alice=50", "--percent", "bob=40"
    )
    assert code == 2
    assert "100" in err
    assert run("list")[1] == ""


def test_with_and_percent_cannot_be_combined(run):
    with pytest.raises(SystemExit):
        run("add", "--paid-by", "alice", "--amount", "10", "--description", "x", "--with", "bob", "--percent", "bob=100")
EOF
python -m pytest -q 2>&1 | tail -3

